class DemoDataService { DemoDataService(this.database,this.clock); final AppDatabase database; final AppClock clock; static const seedVersion=1; Future<int?> getSeedVersion() async { final row=await database.customSelect("SELECT value FROM app_settings WHERE key='demo_seed_version'").getSingleOrNull(); return int.tryParse(row?.read<String>('value')??''); }
 Future<void> ensureSeeded() async { if(await getSeedVersion()==seedVersion)return; await resetAndSeed(); }
 Future<void> resetAndSeed()=>database.transaction(() async { await database.customStatement('PRAGMA defer_foreign_keys = ON'); for(final table in const ['role_permissions','team_memberships','task_approvals','deadline_extension_requests','task_blockers','task_attachments','task_comments','checklist_items','task_assignments','audit_events','sync_operations','app_notifications','tasks','recurrence_rules','task_templates','notification_templates','escalation_rules','approval_rules','categories','priorities','confidentiality_levels','teams','users','permissions','roles','departments','organizations','saved_task_filters','app_settings']) { await database.customStatement('DELETE FROM $table'); } await _seed(); });
