 await database.customStatement("INSERT INTO audit_events VALUES ('audit-reassignment','scenario-08','task','scenario-08','reassigned','user-sara-mahmoud',?,NULL,NULL,'Operational coverage','demo-device',0,'synced')",[iso]);
 await database.customStatement("INSERT INTO sync_operations VALUES ('sync-offline','task','scenario-12','update','{}',?,NULL,0,'pending',NULL,'none')",[iso]); await database.customStatement("INSERT INTO sync_operations VALUES ('sync-conflict','task','scenario-13','update','{}',?,NULL,1,'conflict','Assignment changed','assignment')",[iso]);
 // Complete Phase 02 configuration and relationships.
 for(final c in const [('confidentiality-public','public','عام','Public',0),('confidentiality-confidential','confidential','سري','Confidential',2),('confidentiality-restricted','restricted','مقيد','Restricted',3)]) { await database.customStatement("INSERT INTO confidentiality_levels VALUES (?,?,?,?,?,'standard',1,?)",[c.$1,c.$2,c.$3,c.$4,c.$5,c.$5]); }
 for(final p in const [('permission-view','view_tasks'),('permission-manage','manage_tasks'),('permission-approve','approve_tasks'),('permission-reports','view_reports'),('permission-admin','administer_system')]) { await database.customStatement('INSERT INTO permissions VALUES (?,?)',[p.$1,p.$2]); }
 var rp=0; for(final role in const [DemoSeedIds.roleEmployee,DemoSeedIds.roleManager,DemoSeedIds.roleSenior,DemoSeedIds.roleAdministrator]) { for(final permission in const ['permission-view','permission-manage','permission-approve','permission-reports','permission-admin']) { if(role==DemoSeedIds.roleEmployee&&permission!='permission-view') continue; await database.customStatement('INSERT INTO role_permissions VALUES (?,?,?)',['role-permission-${rp++}',role,permission]); } }
