 for(var i=1;i<=12;i++){await database.customStatement('INSERT INTO team_memberships VALUES (?,?,?,?,1,?,NULL)',['membership-copy-$i',i.isEven?DemoSeedIds.accountsPayable:DemoSeedIds.employeeServices,'user-copy-$i','member',iso]);}
